void __stdcall ExtractItemDetails(uint8_t * pBytesAfterId, size_t size, BOOL isSave, D2UnitDataItemDetailsStrc * itemData) {
    ReadInfoFromStreamVersioned(pBytesAfterId, size, isSave, itemData, 0x60);
}

// Deserialises an item unit from a binary save-data bit buffer into pUnit. Validates the 0x4D4A ("JM") magic header when nParam1 is set, reads the 32-bit item flags word, strips invalid flags, resets all affix/prefix/suffix fields on the unit to clean state, then delegates to ITEM_DeserializeFromBitBuffer (full items) or ITEMS_DeserializeItemHeader (compact items). Returns the number of bits consumed.
int32_t __stdcall ITEM_LoadFromSaveData(D2UnitStrc * pUnit, uint8_t * pbParam, size_t nSize, uint32_t nParam1, uint32_t * pnParam, uint32_t nParam2, int * pUnitDataItemDetails) {
    int32_t nBitsConsumed;
    int32_t nDeserializeResult;
    D2BitBufferStrc sBitBuffer;
    Fog::BitBuffer::InitBitBuffer(&sBitBuffer, pbParam, nSize);
    if (nParam1) {
      nBitsConsumed = Fog::BitBuffer::ReadSigned(&sBitBuffer, 0x10);
      if (nBitsConsumed != 0x4d4a) {
        *pUnitDataItemDetails = 1;
        return 0;
      }
    }

    *pUnitDataItemDetails = 0;
    eD2ItemFlag eItemFlags = Fog::BitBuffer::ReadUnsigned(&sBitBuffer, 0x20);
    bool bIsExtended = (eItemFlags & ITEMFLAG_CRUDE) != ~(ITEMFLAG_TAGGED | ITEMFLAG_DROW | ITEMFLAG_CURSED | ITEMFLAG_STAFFMODS | ITEMFLAG_MAGICAL | ITEMFLAG_RUNEWORD | ITEMFLAG_CRUDE | ITEMFLAG_PLAYERNAME | ITEMFLAG_SAVED | ITEMFLAG_ETHEREAL | ITEMFLAG_COMPACT | ITEMFLAG_100000 | ITEMFLAG_SERVER | ITEMFLAG_RESTRICT | ITEMFLAG_BEGINNER | ITEMFLAG_BODYPART | ITEMFLAG_HARDCORE | ITEMFLAG_DISABLED | ITEMFLAG_NEW | ITEMFLAG_MONSTER | ITEMFLAG_SOCKETED | ITEMFLAG_SORTED | ITEMFLAG_RESTORED | ITEMFLAG_BROKEN | ITEMFLAG_TAKEN | ITEMFLAG_ADDED | ITEMFLAG_REMOVED | ITEMFLAG_IDENTIFIED | ITEMFLAG_IGNORE | ITEMFLAG_CURSOR | ITEMFLAG_BOUGHT | ITEMFLAG_RELOAD);
    if (bIsExtended) {
      eItemFlags &= ITEMFLAG_TAGGED | ITEMFLAG_DROW | ITEMFLAG_CURSED | ITEMFLAG_STAFFMODS | ITEMFLAG_MAGICAL | ITEMFLAG_RUNEWORD | ITEMFLAG_PLAYERNAME | ITEMFLAG_SAVED | ITEMFLAG_ETHEREAL | ITEMFLAG_COMPACT | ITEMFLAG_100000 | ITEMFLAG_SERVER | ITEMFLAG_RESTRICT | ITEMFLAG_BEGINNER | ITEMFLAG_BODYPART | ITEMFLAG_HARDCORE | ITEMFLAG_DISABLED | ITEMFLAG_NEW | ITEMFLAG_MONSTER | ITEMFLAG_SOCKETED | ITEMFLAG_SORTED | ITEMFLAG_RESTORED | ITEMFLAG_BROKEN | ITEMFLAG_TAKEN | ITEMFLAG_ADDED | ITEMFLAG_REMOVED | ITEMFLAG_IDENTIFIED | ITEMFLAG_IGNORE | ITEMFLAG_CURSOR | ITEMFLAG_BOUGHT | ITEMFLAG_RELOAD;
    }
    if (pUnit) {
      eD2ItemFlag* pItemFlags;
      if (pUnit->eUnitType == UNIT_ITEM && pUnit->pUnitData.pUnitDataItem) {
        pUnit->pUnitData.pUnitDataItem->dwItemFlags = ~(ITEMFLAG_TAGGED | ITEMFLAG_DROW | ITEMFLAG_CURSED | ITEMFLAG_STAFFMODS | ITEMFLAG_MAGICAL | ITEMFLAG_RUNEWORD | ITEMFLAG_CRUDE | ITEMFLAG_PLAYERNAME | ITEMFLAG_SAVED | ITEMFLAG_ETHEREAL | ITEMFLAG_COMPACT | ITEMFLAG_100000 | ITEMFLAG_SERVER | ITEMFLAG_RESTRICT | ITEMFLAG_BEGINNER | ITEMFLAG_BODYPART | ITEMFLAG_HARDCORE | ITEMFLAG_DISABLED | ITEMFLAG_NEW | ITEMFLAG_MONSTER | ITEMFLAG_SOCKETED | ITEMFLAG_SORTED | ITEMFLAG_RESTORED | ITEMFLAG_BROKEN | ITEMFLAG_TAKEN | ITEMFLAG_ADDED | ITEMFLAG_REMOVED | ITEMFLAG_IDENTIFIED | ITEMFLAG_IGNORE | ITEMFLAG_CURSOR | ITEMFLAG_BOUGHT | ITEMFLAG_RELOAD);
      }
      if (pUnit->eUnitType == UNIT_ITEM) {
        if (pUnit->pUnitData.pUnitDataItem) {
          pItemFlags = &pUnit->pUnitData.pUnitDataItem->dwItemFlags;
          *pItemFlags |= eItemFlags;
        }
        if (pUnit->eUnitType == UNIT_ITEM) {
          if (pUnit->pUnitData.pUnitDataItem) {
            pItemFlags = &pUnit->pUnitData.pUnitDataItem->dwItemFlags;
            *pItemFlags &= ITEMFLAG_TAGGED | ITEMFLAG_DROW | ITEMFLAG_CURSED | ITEMFLAG_STAFFMODS | ITEMFLAG_MAGICAL | ITEMFLAG_RUNEWORD | ITEMFLAG_CRUDE | ITEMFLAG_PLAYERNAME | ITEMFLAG_SAVED | ITEMFLAG_ETHEREAL | ITEMFLAG_COMPACT | ITEMFLAG_100000 | ITEMFLAG_RESTRICT | ITEMFLAG_BEGINNER | ITEMFLAG_BODYPART | ITEMFLAG_HARDCORE | ITEMFLAG_DISABLED | ITEMFLAG_NEW | ITEMFLAG_MONSTER | ITEMFLAG_SOCKETED | ITEMFLAG_SORTED | ITEMFLAG_RESTORED | ITEMFLAG_BROKEN | ITEMFLAG_TAKEN | ITEMFLAG_ADDED | ITEMFLAG_REMOVED | ITEMFLAG_IDENTIFIED | ITEMFLAG_IGNORE | ITEMFLAG_CURSOR | ITEMFLAG_BOUGHT | ITEMFLAG_RELOAD;
          }
          if (pUnit->eUnitType == UNIT_ITEM) {
            if (pUnit->pUnitData.pUnitDataItem) {
              pUnit->pUnitData.pUnitDataItem->nItemLevel = 1;
            }
            if (pUnit->eUnitType == UNIT_ITEM) {
              if (pUnit->pUnitData.pUnitDataItem) {
                pUnit->pUnitData.pUnitDataItem->wMagicPrefix[0] = 0;
              }
              if (pUnit->eUnitType == UNIT_ITEM) {
                if (pUnit->pUnitData.pUnitDataItem) {
                  pUnit->pUnitData.pUnitDataItem->wMagicSuffix[0] = 0;
                }
                if (pUnit->eUnitType == UNIT_ITEM) {
                  if (pUnit->pUnitData.pUnitDataItem) {
                    pUnit->pUnitData.pUnitDataItem->wMagicPrefix[1] = 0;
                  }
                  if (pUnit->eUnitType == UNIT_ITEM) {
                    if (pUnit->pUnitData.pUnitDataItem) {
                      pUnit->pUnitData.pUnitDataItem->wMagicSuffix[1] = 0;
                    }
                    if (pUnit->eUnitType == UNIT_ITEM) {
                      if (pUnit->pUnitData.pUnitDataItem) {
                        pUnit->pUnitData.pUnitDataItem->wMagicPrefix[2] = 0;
                      }
                      if (pUnit->eUnitType == UNIT_ITEM) {
                        if (pUnit->pUnitData.pUnitDataItem) {
                          pUnit->pUnitData.pUnitDataItem->wMagicSuffix[2] = 0;
                        }
                        if (pUnit->eUnitType == UNIT_ITEM) {
                          if (pUnit->pUnitData.pUnitDataItem) {
                            pUnit->pUnitData.pUnitDataItem->wRarePrefix = 0;
                          }
                          if (pUnit->eUnitType == UNIT_ITEM && pUnit->pUnitData.pUnitDataItem) {
                            pUnit->pUnitData.pUnitDataItem->wRareSuffix = 0;
                          }
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
    if ((eItemFlags & ITEMFLAG_COMPACT) != ~(ITEMFLAG_TAGGED | ITEMFLAG_DROW | ITEMFLAG_CURSED | ITEMFLAG_STAFFMODS | ITEMFLAG_MAGICAL | ITEMFLAG_RUNEWORD | ITEMFLAG_CRUDE | ITEMFLAG_PLAYERNAME | ITEMFLAG_SAVED | ITEMFLAG_ETHEREAL | ITEMFLAG_COMPACT | ITEMFLAG_100000 | ITEMFLAG_SERVER | ITEMFLAG_RESTRICT | ITEMFLAG_BEGINNER | ITEMFLAG_BODYPART | ITEMFLAG_HARDCORE | ITEMFLAG_DISABLED | ITEMFLAG_NEW | ITEMFLAG_MONSTER | ITEMFLAG_SOCKETED | ITEMFLAG_SORTED | ITEMFLAG_RESTORED | ITEMFLAG_BROKEN | ITEMFLAG_TAKEN | ITEMFLAG_ADDED | ITEMFLAG_REMOVED | ITEMFLAG_IDENTIFIED | ITEMFLAG_IGNORE | ITEMFLAG_CURSOR | ITEMFLAG_BOUGHT | ITEMFLAG_RELOAD)) {
      nDeserializeResult = ITEMS_DeserializeItemHeader(nParam1, nParam2, pUnit, &sBitBuffer);
      if (pnParam) {
        *pnParam = 0;
      }
    } else {
      nDeserializeResult = ITEM_DeserializeFromBitBuffer(pUnit, &sBitBuffer, nParam1, (D2ItemStatCostTxt*)(uint32_t)bIsExtended, pnParam, nParam2);
    }
    if (nDeserializeResult < 1) {
      *pUnitDataItemDetails = 1;
    }

    nBitsConsumed = Fog::BitBuffer::GetNextPositon(&sBitBuffer);
    return nBitsConsumed;
}

// Returns 1 if pUnit (item) is replenishable (throwable, stackable, non-ethereal, and its ItemTypesTxt entry has the repair flag set). Returns 0 for non-item units or items that fail any condition. Halts on null pUnit.
static BOOL ITEM_IsReplenishable(D2UnitStrc * pUnit) {
    eD2ItemTypes eItemType;
    int32_t nErrLine;
    if (!pUnit) {
      Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x67d);
      exit(-1);
    }
    if (pUnit->eUnitType != UNIT_ITEM) {
      eItemType = ITEMTYPE_None1;
    } else {
      eItemType = TXT_Items_GetType(pUnit->nClassId);
      if ((int)eItemType < 0) {
        return 0;
      }
    }
    if (!((int)eItemType < sgptDataTable->nTxtItemTypesSize && sgptDataTable->pTxtItemTypes + eItemType && sgptDataTable->pTxtItemTypes[eItemType].repair != '\0')) {
      return 0;
    }

    nErrLine = ITEM_GetTxtItemTypes_throwable(pUnit);
    if (!nErrLine) {
      return 0;
    }

    BOOL bIsStackable = IsStackable(pUnit);
    if (!bIsStackable) {
      return 0;
    }

    uint32_t bIsEthereal = ITEM_GetItemData_eD2ItemFlag_IsEthereal(pUnit);
    if (bIsEthereal) {
      return 0;
    }

    return 1;
}

// Returns 1 if the item unit can be repaired at an NPC. Checks: must be an identified, non-ethereal item whose ItemTypesTxt entry has the repair flag, is not replenishable, and has durability. Also passes if the item's charged skills are not fully charged.
uint32_t __stdcall ITEM_CanBeRepaired(D2UnitStrc * pUnit) {
    D2UnitStrc* pItemUnit = pUnit;
    if ((pUnit ? pUnit->eUnitType : UNIT_COUNT) != UNIT_ITEM) {
      return 0;
    }

    D2UnitDataItemStrc* pItemData = pUnit->pUnitData.pUnitDataItem;
    if (!pItemData) {
      return 0;
    }
    if ((pItemData->dwItemFlags & ITEMFLAG_IDENTIFIED) == ~(ITEMFLAG_TAGGED | ITEMFLAG_DROW | ITEMFLAG_CURSED | ITEMFLAG_STAFFMODS | ITEMFLAG_MAGICAL | ITEMFLAG_RUNEWORD | ITEMFLAG_CRUDE | ITEMFLAG_PLAYERNAME | ITEMFLAG_SAVED | ITEMFLAG_ETHEREAL | ITEMFLAG_COMPACT | ITEMFLAG_100000 | ITEMFLAG_SERVER | ITEMFLAG_RESTRICT | ITEMFLAG_BEGINNER | ITEMFLAG_BODYPART | ITEMFLAG_HARDCORE | ITEMFLAG_DISABLED | ITEMFLAG_NEW | ITEMFLAG_MONSTER | ITEMFLAG_SOCKETED | ITEMFLAG_SORTED | ITEMFLAG_RESTORED | ITEMFLAG_BROKEN | ITEMFLAG_TAKEN | ITEMFLAG_ADDED | ITEMFLAG_REMOVED | ITEMFLAG_IDENTIFIED | ITEMFLAG_IGNORE | ITEMFLAG_CURSOR | ITEMFLAG_BOUGHT | ITEMFLAG_RELOAD)) {
      return 0;
    }
    if (pItemData && (pItemData->dwItemFlags & ITEMFLAG_ETHEREAL) != ~(ITEMFLAG_TAGGED | ITEMFLAG_DROW | ITEMFLAG_CURSED | ITEMFLAG_STAFFMODS | ITEMFLAG_MAGICAL | ITEMFLAG_RUNEWORD | ITEMFLAG_CRUDE | ITEMFLAG_PLAYERNAME | ITEMFLAG_SAVED | ITEMFLAG_ETHEREAL | ITEMFLAG_COMPACT | ITEMFLAG_100000 | ITEMFLAG_SERVER | ITEMFLAG_RESTRICT | ITEMFLAG_BEGINNER | ITEMFLAG_BODYPART | ITEMFLAG_HARDCORE | ITEMFLAG_DISABLED | ITEMFLAG_NEW | ITEMFLAG_MONSTER | ITEMFLAG_SOCKETED | ITEMFLAG_SORTED | ITEMFLAG_RESTORED | ITEMFLAG_BROKEN | ITEMFLAG_TAKEN | ITEMFLAG_ADDED | ITEMFLAG_REMOVED | ITEMFLAG_IDENTIFIED | ITEMFLAG_IGNORE | ITEMFLAG_CURSOR | ITEMFLAG_BOUGHT | ITEMFLAG_RELOAD)) {
      return 0;
    }

    BOOL nCheckResult = ITEMS_CheckChargedSkillFullyCharged(pUnit, (bool*)&pUnit);
    if (!(!nCheckResult || pUnit)) {
      return 1;
    }

    eD2ItemTypes eItemType = ITEM_GetItemData_wType(pItemUnit);
    D2ItemTypesTxt* pItemTypesTxt = D2Game::ITEMS::Items::Drop::ItemTypes_GetLine(eItemType);
    if (!pItemTypesTxt) {
      return 0;
    }
    if (pItemTypesTxt->repair == '\0') {
      return 0;
    }

    nCheckResult = ITEM_IsReplenishable(pItemUnit);
    if (nCheckResult) {
      return 1;
    }

    uint32_t bHasDurabilityFlag = ITEM_CheckIfItemHasDurability(pItemUnit);
    return (uint32_t)(bHasDurabilityFlag != 0);
}

